package io.github.diodeme.ji.acp.v2.preview;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.StreamReadConstraints;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Strict codec for the pinned ACP v2-preview subset used by JI. */
public final class AcpV2PreviewCodec {
    private final ObjectMapper mapper;

    public AcpV2PreviewCodec(int maximumDepth, int maximumStringLength) {
        mapper = new ObjectMapper();
        mapper.getFactory().setStreamReadConstraints(StreamReadConstraints.builder()
                .maxNestingDepth(maximumDepth).maxStringLength(maximumStringLength).build());
    }

    public JsonNode read(String json) {
        try {
            return mapper.readTree(json);
        } catch (JsonProcessingException failure) {
            throw new IllegalArgumentException("ACP v2-preview message is invalid", failure);
        }
    }

    public String write(Object value) {
        try {
            return mapper.writeValueAsString(value);
        } catch (JsonProcessingException failure) {
            throw new IllegalArgumentException("ACP v2-preview message cannot be encoded", failure);
        }
    }

    public Map<String, Object> stateUpdate(String sessionId, AcpV2PreviewModel.StateUpdate state) {
        Map<String, Object> update = new LinkedHashMap<>();
        update.put("sessionUpdate", "state_update");
        if (state instanceof AcpV2PreviewModel.StateUpdate.Running) update.put("state", "running");
        else if (state instanceof AcpV2PreviewModel.StateUpdate.RequiresAction) update.put("state", "requires_action");
        else if (state instanceof AcpV2PreviewModel.StateUpdate.Idle idle) {
            update.put("state", "idle");
            idle.stopReason().ifPresent(reason -> update.put("stopReason", reason));
        }
        return Map.of("sessionId", sessionId, "update", update);
    }

    public Map<String, Object> messageUpdate(AcpV2PreviewModel.Message message) {
        String kind = message.role() == AcpV2PreviewModel.Role.USER ? "user_message" : "agent_message";
        return Map.of("sessionUpdate", kind, "messageId", message.id(),
                "content", List.of(Map.of("type", "text", "text", message.text())));
    }

    public Map<String, Object> diff(AcpV2PreviewModel.StructuredDiff value) {
        var changes = new ArrayList<Map<String, Object>>();
        for (AcpV2PreviewModel.Change change : value.changes()) {
            Map<String, Object> encoded = new LinkedHashMap<>();
            encoded.put("operation", change.operation().name().toLowerCase(java.util.Locale.ROOT));
            if (change.oldPath() != null) encoded.put("oldPath", change.oldPath());
            encoded.put("path", change.path());
            if (change.fileType() != null) encoded.put("fileType", change.fileType());
            if (change.mimeType() != null) encoded.put("mimeType", change.mimeType());
            changes.add(encoded);
        }
        Map<String, Object> result = new LinkedHashMap<>();
        result.put("type", "diff");
        result.put("changes", changes);
        value.patch().ifPresent(patch -> result.put("patch", Map.of("format", patch.format(), "text", patch.text())));
        return result;
    }

    public AcpV2PreviewModel.ReplayFrom replayFrom(JsonNode node) {
        if (node != null && "start".equals(node.path("type").asText())) return new AcpV2PreviewModel.ReplayFrom.Start();
        throw new IllegalArgumentException("ACP v2-preview replay cursor is unsupported");
    }
}
